/**
 * pi supports a single working directory per session; additionalDirectories is
 * accepted (per the ACP extensibility rule) but cannot be honored, so warn
 * instead of failing the request. The capability is never advertised.
 */
function warnAdditionalDirectories(method: string, dirs: unknown): void {
  if (Array.isArray(dirs) && dirs.length > 0) {
    process.stderr
      .write(`[pi-acp] ${method}: additionalDirectories is not supported by pi; ignoring ${dirs.length} path(s)
`)
  }
}

/** Parse an integer env override, falling back to the given default. */
function respawnEnvInt(name: string, fallback: number): number {
  const raw = process.env[name]
  if (raw === undefined || raw.trim() === '') return fallback
  const value = Number.parseInt(raw, 10)
  return Number.isFinite(value) && value >= 0 ? value : fallback
}

export class PiAcpAgent {
  private readonly conn: AcpClient
  private readonly sessions = new SessionManager()
  /** cwd per session id, kept for the adapter's lifetime: pi's session file is derived from id + cwd. */
  private readonly cwds = new Map<string, string>()
  private clientCapabilities: ClientCapabilities = {}
  private readonly restoringSessions = new Map<string, Promise<PiAcpSession>>()
  /**
   * Launch options per session id, kept for the adapter's lifetime so a respawn after a
   * pi crash relaunches with the same flags and system prompt.
   */
  private readonly launches = new Map<string, LaunchOptions>()

  /**
   * Respawn guard for on-demand recovery (codex AppServerRecovery pattern): a stored
   * session whose pi process keeps dying must not be respawned without bound. Each
   * on-demand restore (a request for a session that has no live process; `session/load`
   * and `session/resume` restore by the client's own choice and do not count) acquires
   * a per-session slot; strikes are isolated per session so
   * one bad session cannot lock out others. Tunable via PI_ACP_RESPAWN_* env vars.
   */
  private readonly respawnAttempts = new Map<string, number[]>()
  // Env overrides are read per attempt (not at class-definition time) so operators
  // and tests can tune them after module load.
  private get respawnWindowMs(): number {
    return respawnEnvInt('PI_ACP_RESPAWN_WINDOW_MS', 10 * 60 * 1000)
  }
  private get respawnMaxAttempts(): number {
    return respawnEnvInt('PI_ACP_RESPAWN_MAX_ATTEMPTS', 3)
  }

  /**
   * Records a restore attempt, refusing spawns beyond the per-session budget.
   * Synchronous by design: the common path must not add microtasks before the
   * spawn call. No sleep-based backoff: fast consecutive restores are legitimate
   * (client reloads, test flows), and the budget cap already bounds a crash loop.
   */
  private tryAcquireRespawnSlot(sessionId: string): void {
    const now = Date.now()
    const windowStart = now - this.respawnWindowMs
    const attempts = (this.respawnAttempts.get(sessionId) ?? []).filter(ts => ts >= windowStart)
    if (attempts.length >= this.respawnMaxAttempts) {
      const message = `pi respawn budget exhausted for session ${sessionId}: ${attempts.length} restore attempts within ${Math.round(this.respawnWindowMs / 1000)}s; refusing another respawn until the window clears`
      process.stderr.write(`[pi-acp] ${message}\n`)
      throw RequestError.internalError({ reason: 'respawn_budget_exhausted' }, message)
    }
    attempts.push(now)
    this.respawnAttempts.set(sessionId, attempts)
  }

  dispose(): void {
    this.sessions.disposeAll()
  }

  // Remember recent session cwd and use it as the default filter.
  private lastSessionCwd: string | null = null

  constructor(conn: AcpClient, _config?: unknown) {
    this.conn = conn
    void _config
  }

  private async cleanupFailedNewSession(sessionId: string, state?: any | null): Promise<void> {
    this.sessions.close(sessionId)

    const sessionFile =
      typeof state?.sessionFile === 'string' && state.sessionFile.trim()
        ? state.sessionFile
        : await this.locateSessionFile(sessionId, this.cwds.get(sessionId))

    if (typeof sessionFile === 'string' && sessionFile.trim()) {
      try {
        await rm(sessionFile, { force: true })
      } catch {
        // ignore cleanup failures; the auth/internal error is the primary result
      }
    }

    this.cwds.delete(sessionId)
  }

  private async locateSessionFile(sessionId: string, cwd: string | undefined): Promise<string | null> {
    return cwd ? findPiSessionFile(getPiSessionDirForCwd(cwd), sessionId) : null
  }

  /** The session's file, or an error naming the id and the directory searched. */
  private async requireSessionFile(sessionId: string, cwd: string): Promise<string> {
    const file = await this.locateSessionFile(sessionId, cwd)
    if (file) return file
    const dir = getPiSessionDirForCwd(cwd)
    throw RequestError.invalidParams({ sessionId, dir }, `No pi session file for session ${sessionId} in ${dir}`)
  }

  private async restoreSession(
    sessionId: string,
    opts?: { cwd?: string; mcpServers?: LoadSessionRequest['mcpServers']; launch?: LaunchOptions }
  ): Promise<PiAcpSession> {
    if (opts?.launch) this.launches.set(sessionId, opts.launch)
    const existing = this.sessions.maybeGet(sessionId)
    if (existing) return existing

    const inFlight = this.restoringSessions.get(sessionId)
    if (inFlight) return inFlight

    const restorePromise = (async () => {
      const cwd = opts?.cwd ?? this.cwds.get(sessionId)
      if (!cwd) throw RequestError.invalidParams(`Unknown sessionId: ${sessionId}`)
      const sessionFile = await this.requireSessionFile(sessionId, cwd)

      if (!opts?.cwd) this.tryAcquireRespawnSlot(sessionId)

      const mcpInjection = opts?.mcpServers?.length ? prepareMcpInjection(opts.mcpServers) : null
      let proc: PiRpcProcess
      try {
        const launch = this.launches.get(sessionId)
        proc = await PiRpcProcess.spawn({
          cwd,
          sessionPath: sessionFile,
          piCommand: process.env.PI_ACP_PI_COMMAND,
          ...(mcpInjection ? { mcpInjection } : {}),
          ...(launch?.args.length ? { launchArgs: launch.args } : {}),
          ...(launch?.systemPrompt ? { systemPrompt: launch.systemPrompt } : {})
        })
      } catch (e: any) {
        mcpInjection?.cleanup()
        if (e?.name === 'PiRpcSpawnError') {
          throw RequestError.internalError({ code: e?.code }, String(e?.message ?? e))
        }
        throw e
      }

      const fileCommands = loadSlashCommands(cwd)
      const session = this.sessions.getOrCreate(sessionId, {
        cwd,
        mcpServers: opts?.mcpServers ?? [],
        conn: this.conn,
        proc,
        fileCommands,
        mcpInjection,
        clientCapabilities: this.clientCapabilities,
        ...(this.launches.has(sessionId) ? { launch: this.launches.get(sessionId) } : {})
      })

      try {
        this.lastSessionCwd = cwd
        this.cwds.set(sessionId, cwd)

        const title = await readPiSessionTitle(sessionFile)
        if (title) await session.publishTitle(title, null)

        return session
      } catch (err) {
        this.sessions.close(sessionId)
        throw err
      }
    })()

    this.restoringSessions.set(sessionId, restorePromise)

    try {
      return await restorePromise
    } finally {
      this.restoringSessions.delete(sessionId)
    }
  }

  async initialize(params: InitializeRequest): Promise<InitializeResponse> {
    this.clientCapabilities = params.clientCapabilities ?? {}
    // We currently only support ACP protocol version 1.
    const supportedVersion = PROTOCOL_VERSION
    const requested = params.protocolVersion

    const response: InitializeResponse = {
      _meta: { steering: { supported: true } },
      protocolVersion: requested === supportedVersion ? requested : supportedVersion,
      agentInfo: {
        name: 'pi-acp',
        title: 'pi ACP adapter',
        version: pkg.version ?? '0.0.0'
      },
      // Zed currently uses ClientCapabilities._meta["terminal-auth"] to decide whether to show
      // the "Authenticate" banner/button. If not supported, we still return the method for the registry.
      authMethods: getAuthMethods({
        supportsTerminalAuth: this.clientCapabilities.auth?.terminal === true,
        supportsTerminalAuthMeta: this.clientCapabilities._meta?.['terminal-auth'] === true
      }),
      agentCapabilities: {
        loadSession: true,
        // pi connects streamable-HTTP MCP entries natively; SSE entries are skipped
        // in mcp-descriptor.ts, so the capability claim stays honest.
        mcpCapabilities: { http: true, sse: false },
        promptCapabilities: {
          image: true,
          audio: false,
          embeddedContext: process.env.PI_ACP_ENABLE_EMBEDDED_CONTEXT === 'true'
        },
        sessionCapabilities: {
          // **UNSTABLE** ACP capability used by Zed's codex-acp adapter.
          // Enables a native session picker in clients that support it.
          list: {},
          delete: {},
          resume: {},
          close: {},
          // **UNSTABLE** Fork branches the stored pi session file into a new
          // session via pi's native `--fork`.
          fork: {}
        },
        _meta: {
          // Per-session launch options this adapter reads from request _meta (see acp/launch.ts).
          piAcp: launchCapabilities(),
          // UNSTABLE claude-agent-acp contract. Auth discovery can read either this
          // marker or the _auth/status_update push below; both need a complete
          // kind/label identity, since an empty marker can stall model discovery.
          authStatus: {
            kind: 'api_key',
            label: 'pi',
            detail: 'provider credentials managed by pi'
          }
        }
      }
    }

    // Some clients await this optional auth-status push before model discovery.
    // Send it after initialization; clients without the extension can ignore it.
    setTimeout(() => {
      // Optional call: test fakes may not implement extension notifications.
      void this.conn
        .extNotification?.('_auth/status_update', {
          authStatus: {
            kind: 'api_key',
            label: 'pi',
            detail: 'provider credentials managed by pi'
          }
        })
        ?.catch(() => {})
    }, 0)

    return response
  }

  async newSession(params: NewSessionRequest) {
    if (!isAbsolute(params.cwd)) {
      throw RequestError.invalidParams(`cwd must be an absolute path: ${params.cwd}`)
    }
    warnAdditionalDirectories('session/new', (params as { additionalDirectories?: unknown }).additionalDirectories)
    const launch = parseLaunchOptions(params._meta)

    // Version discovery runs concurrently with the pi spawn below and never blocks the
    // loop (no synchronous `pi --version` / `npm view` probes on session/new).
    const versionProbe: Promise<{ installed: string | null; latest: string | null }> = launch.headless
      ? Promise.resolve({ installed: null, latest: null })
      : probeVersions()

    this.lastSessionCwd = params.cwd

    const fileCommands = loadSlashCommands(params.cwd)
    const enableSkillCommands = getEnableSkillCommands(params.cwd)

    // Pi doesn't support mcpServers, but we accept and store.
    const session = await this.sessions.create({
      cwd: params.cwd,
      mcpServers: params.mcpServers,
      conn: this.conn,
      fileCommands,
      piCommand: process.env.PI_ACP_PI_COMMAND,
      clientCapabilities: this.clientCapabilities,
      launch
    })
    this.launches.set(session.sessionId, launch)
    this.cwds.set(session.sessionId, params.cwd)

    // Fetch state + models once (parallel) to reduce startup latency.
    let state: any = null
    let availableModels: any = null
    let stateErr: unknown = null
    let availableModelsErr: unknown = null

    await Promise.all([
      session.proc
        .getState()
        .then(s => {
          state = s as any
        })
        .catch(err => {
          stateErr = err
          state = null
        }),
      session.proc
        .getAvailableModels()
        .then(m => {
          availableModels = m as any
        })
        .catch(err => {
          availableModelsErr = err
          availableModels = null
        })
    ])

    const availableModelsAuthErr = maybeAuthRequiredError(availableModelsErr, this.clientCapabilities)

    if (availableModelsAuthErr) {
      await this.cleanupFailedNewSession(session.sessionId, state)
      throw availableModelsAuthErr
    }

    if (availableModelsErr) {
      await this.cleanupFailedNewSession(session.sessionId, state)
      throw RequestError.internalError({}, String((availableModelsErr as Error)?.message ?? availableModelsErr))
    }

    // If pi has no models available after spawning, it's effectively unauthenticated.
    const rawModelsCount = Array.isArray(availableModels?.models) ? availableModels.models.length : 0

    if (rawModelsCount === 0) {
      await this.cleanupFailedNewSession(session.sessionId, state)
      throw RequestError.authRequired(
        {
          authMethods: getAuthMethods({
            supportsTerminalAuth: this.clientCapabilities.auth?.terminal === true,
            supportsTerminalAuthMeta: this.clientCapabilities._meta?.['terminal-auth'] === true
          })
        },
        'Configure an API key or log in with an OAuth provider.'
      )
    }

    if (stateErr && maybeAuthRequiredError(stateErr, this.clientCapabilities)) {
      await this.cleanupFailedNewSession(session.sessionId, state)
      throw RequestError.authRequired(
        {
          authMethods: getAuthMethods({
            supportsTerminalAuth: this.clientCapabilities.auth?.terminal === true,
            supportsTerminalAuthMeta: this.clientCapabilities._meta?.['terminal-auth'] === true
          })
        },
        'Configure an API key or log in with an OAuth provider.'
      )
    }

    let configuration: Awaited<ReturnType<typeof getSessionConfiguration>>
    try {
      if (stateErr) throw stateErr
      configuration = await getSessionConfiguration(session.proc, { state, availableModels })
    } catch (err) {
      await this.cleanupFailedNewSession(session.sessionId, state)
      throw (
        maybeAuthRequiredError(err, this.clientCapabilities) ??
        RequestError.internalError({}, String((err as Error)?.message ?? err))
      )
    }
    const { configOptions, models, modes } = configuration

    // Headless children get no banner and no update probe (it runs `npm view`).
    const quietStartup = launch.headless || getQuietStartup(params.cwd)
    const { installed: piVersion, latest } = await versionProbe
    const updateNotice = buildUpdateNotice(piVersion, latest)

    // If quietStartup is enabled, suppress the full "startup info" prelude, but still surface
    // the "New version available" notice (if any) since it's high-signal and actionable.
    let preludeText = quietStartup
      ? updateNotice
        ? updateNotice + '\n'
        : ''
      : buildStartupInfo({
          cwd: params.cwd,
          fileCommands,
          updateNotice,
          piVersion
        })

    const mcpSection = launch.headless ? null : buildMcpStartupSection(session.mcpInjection)
    if (mcpSection) preludeText = preludeText ? `${preludeText}${mcpSection}` : mcpSection

    if (preludeText) session.setStartupInfo(preludeText)

    const response = {
      sessionId: session.sessionId,
      configOptions,
      models,
      modes,
      _meta: {
        piAcp: {
          startupInfo: preludeText || null
        }
      }
    }

    // Try to send it immediately after session/new returns; if the client ignores it,
    // it will still be emitted as the first chunk of the first prompt.
    if (preludeText) setTimeout(() => session.sendStartupInfoIfPending(), 0)

    // Advertise slash commands (ACP: available_commands_update)
    // Important: some clients (e.g. Zed) will ignore notifications for an unknown sessionId.
    // So we must send this *after* the session/new response has been delivered.
    setTimeout(() => {
      void (async () => {
        // Publish real context usage now that the client knows the sessionId (clients ignore
        // notifications for unknown sessions), so the window size is correct before the first prompt.
        await session.publishContextUsage()

        try {
          const pi = (await session.proc.getCommands()) as any
          const { commands } = toAvailableCommandsFromPiGetCommands(pi, {
            enableSkillCommands,
            includeExtensionCommands: true
          })

          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'available_commands_update',
              availableCommands: mergeCommands(commands, builtinAvailableCommands())
            }
          })
          return
        } catch {
          // Fall back to file-based prompt templates (legacy behavior).
        }

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'available_commands_update',
            availableCommands: mergeCommands(toAvailableCommands(fileCommands), builtinAvailableCommands())
          }
        })
      })()
    }, 0)

    return response
  }

  /**
   * Some clients query providers during initialization before creating a session.
   * Pi owns provider configuration, so return an empty catalog rather than a missing-method error.
   */
  async unstable_listProviders(_params: ListProvidersRequest): Promise<ListProvidersResponse> {
    return { providers: [] }
  }

  async authenticate(_params: AuthenticateRequest) {
    // Terminal Auth is handled out-of-band by re-launching the binary with `--terminal-login`.
    // If the client calls `authenticate` anyway, we can no-op successfully.
    return
  }

  async prompt(params: PromptRequest, signal?: AbortSignal): Promise<PromptResponse> {
    if (signal?.aborted) return { stopReason: 'cancelled' }
    try {
      const response = await this.runPrompt(params, signal)
      return signal?.aborted ? { stopReason: 'cancelled' } : response
    } catch (error) {
      if (signal?.aborted) {
        return { stopReason: 'cancelled' }
      }
      throw error
    }
  }

  private async runPrompt(params: PromptRequest, signal?: AbortSignal): Promise<PromptResponse> {
    const session = await this.restoreSession(params.sessionId)
    if (signal?.aborted) return { stopReason: 'cancelled' }

    const { message, images } = promptToPiMessage(params.prompt)

    // Built-in ACP slash command handling (headless-friendly subset).
    // Note: file-based slash commands are expanded inside session.prompt().
    if (images.length === 0 && message.trimStart().startsWith('/')) {
      const trimmed = message.trim()
      const space = trimmed.indexOf(' ')
      const cmd = space === -1 ? trimmed.slice(1) : trimmed.slice(1, space)
      const argsString = space === -1 ? '' : trimmed.slice(space + 1)
      const args = parseCommandArgs(argsString)

      if (cmd === 'compact') {
        const customInstructions = args.join(' ').trim() || undefined
        const compact = await session.compact(customInstructions, signal)
        if (compact.cancelled) return { stopReason: 'cancelled' }
        const res = compact.result
        if (this.clientCapabilities.session?.compaction != null) return { stopReason: 'end_turn' }

        const r: any = res && typeof res === 'object' ? (res as any) : null
        const tokensBefore = typeof r?.tokensBefore === 'number' ? r.tokensBefore : null
        const summary = typeof r?.summary === 'string' ? r.summary : null

        const headerLines = [
          `Compaction completed.${customInstructions ? ' (custom instructions applied)' : ''}`,
          tokensBefore !== null ? `Tokens before: ${tokensBefore}` : null
        ].filter(Boolean)

        const text = headerLines.join('\n') + (summary ? `\n\n${summary}` : '')

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: { type: 'text', text }
          }
        })

        return { stopReason: 'end_turn' }
      }

      if (cmd === 'session') {
        const stats = await session.proc.getSessionStats()

        const lines: string[] = []
        if (stats?.sessionId) lines.push(`Session: ${stats.sessionId}`)
        if (stats?.sessionFile) lines.push(`Session file: ${stats.sessionFile}`)
        if (typeof stats?.totalMessages === 'number') lines.push(`Messages: ${stats.totalMessages}`)

        if (typeof stats?.cost === 'number') lines.push(`Cost: ${stats.cost}`)

        const t = stats?.tokens
        if (t && typeof t === 'object') {
          const parts: string[] = []
          if (typeof t.input === 'number') parts.push(`in ${t.input}`)
          if (typeof t.output === 'number') parts.push(`out ${t.output}`)
          if (typeof t.cacheRead === 'number') parts.push(`cache read ${t.cacheRead}`)
          if (typeof t.cacheWrite === 'number') parts.push(`cache write ${t.cacheWrite}`)
          if (typeof t.total === 'number') parts.push(`total ${t.total}`)
          if (parts.length) lines.push(`Tokens: ${parts.join(', ')}`)
        }

        // Fallback if stats shape changes.
        const text = lines.length ? lines.join('\n') : `Session stats:\n${JSON.stringify(stats, null, 2)}`

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: { type: 'text', text }
          }
        })

        return { stopReason: 'end_turn' }
      }

      if (cmd === 'name') {
        const name = args.join(' ').trim()
        if (!name) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: { type: 'text', text: 'Usage: /name <name>' }
            }
          })
          return { stopReason: 'end_turn' }
        }

        try {
          await session.setSessionName(name)
        } catch (e: any) {
          const msg = String(e?.message ?? e)
          const hint = /set_session_name/i.test(msg)
            ? ' This requires a newer pi version that supports `set_session_name` in RPC mode.'
            : ''

          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: { type: 'text', text: `Failed to set session name: ${msg}${hint}` }
            }
          })
          return { stopReason: 'end_turn' }
        }

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: { type: 'text', text: `Session name set: ${name}` }
          }
        })

        return { stopReason: 'end_turn' }
      }

      if (cmd === 'steering') {
        const modeRaw = String(args[0] ?? '').toLowerCase()
        const state = (await session.proc.getState()) as any
        const current = String(state?.steeringMode ?? '')

        // If no arg, just report current.
        if (!modeRaw) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: `Steering mode: ${current || 'unknown'}`
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        if (modeRaw !== 'all' && modeRaw !== 'one-at-a-time') {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: 'Usage: /steering all | /steering one-at-a-time'
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        await session.proc.setSteeringMode(modeRaw as 'all' | 'one-at-a-time')

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: { type: 'text', text: `Steering mode set to: ${modeRaw}` }
          }
        })

        return { stopReason: 'end_turn' }
      }

      if (cmd === 'follow-up') {
        const modeRaw = String(args[0] ?? '').toLowerCase()
        const state = (await session.proc.getState()) as any
        const current = String(state?.followUpMode ?? '')

        // If no arg, just report current.
        if (!modeRaw) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: `Follow-up mode: ${current || 'unknown'}`
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        if (modeRaw !== 'all' && modeRaw !== 'one-at-a-time') {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: 'Usage: /follow-up all | /follow-up one-at-a-time'
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        await session.proc.setFollowUpMode(modeRaw as 'all' | 'one-at-a-time')

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: { type: 'text', text: `Follow-up mode set to: ${modeRaw}` }
          }
        })

        return { stopReason: 'end_turn' }
      }

      if (cmd === 'changelog') {
        // Read pi's installed CHANGELOG.md. Adapter-side, no model call.
        const findChangelog = async (): Promise<string | null> => {
          // 1) Locate the installed pi package by resolving the `pi` executable.
          // On Node installs, `pi` typically resolves to .../@earendil-works/pi-coding-agent/dist/cli.js
          try {
            const whichCmd = process.platform === 'win32' ? 'where' : 'which'
            const piPath = await probeOutput(whichCmd, ['pi'], 800)

            if (piPath) {
              const resolved = realpathSync(piPath.split(/\r?\n/)[0]!.trim())
              const pkgRoot = dirname(dirname(resolved))
              const p = join(pkgRoot, 'CHANGELOG.md')
              if (existsSync(p)) return p
            }
          } catch {
            // ignore
          }

          // 2) Fallback: ask npm where global modules live.
          try {
            const root = await probeOutput('npm', ['root', '-g'], 800)
            if (root) {
              const p = join(root, '@earendil-works', 'pi-coding-agent', 'CHANGELOG.md')
              if (existsSync(p)) return p
            }
          } catch {
            // ignore
          }

          return null
        }

        const changelogPath = await findChangelog()
        if (!changelogPath) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: { type: 'text', text: "Changelog not found (couldn't locate pi installation)." }
            }
          })
          return { stopReason: 'end_turn' }
        }

        let text = ''
        try {
          text = readFileSync(changelogPath, 'utf-8')
        } catch (e: any) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: { type: 'text', text: `Failed to read changelog: ${String(e?.message ?? e)}` }
            }
          })
          return { stopReason: 'end_turn' }
        }

        // Keep it reasonably sized in chat.
        const maxChars = 20_000
        if (text.length > maxChars) text = text.slice(0, maxChars) + '\n\n...(truncated)...'

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: { type: 'text', text }
          }
        })

        return { stopReason: 'end_turn' }
      }

      if (cmd === 'export') {
        // For now we always export into the session cwd and do not accept a user-provided path.
        // IMPORTANT: pi's export_html reads the session JSONL file. If it doesn't exist yet
        // (no messages) or is empty, pi throws and RPC mode emits an uncorrelated parse error
        // (no id), which would otherwise hang our request. So we guard here.
        const state = (await session.proc.getState()) as any
        const sessionFile = typeof state?.sessionFile === 'string' ? state.sessionFile : null
        const messageCount = typeof state?.messageCount === 'number' ? state.messageCount : 0

        if (!sessionFile || messageCount === 0 || !existsSync(sessionFile)) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: 'Nothing to export yet (no session messages). Send a prompt first.'
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        try {
          const raw = readFileSync(sessionFile, 'utf-8')
          if (raw.trim().length === 0) {
            await this.conn.sessionUpdate({
              sessionId: session.sessionId,
              update: {
                sessionUpdate: 'agent_message_chunk',
                content: {
                  type: 'text',
                  text: 'Nothing to export yet (empty session file). Send a prompt first.'
                }
              }
            })
            return { stopReason: 'end_turn' }
          }
        } catch {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: "Couldn't read session file for export. Try sending a prompt first."
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        const safeSessionId = session.sessionId.replace(/[^a-zA-Z0-9_-]/g, '_')
        const outputPath = join(session.cwd, `pi-session-${safeSessionId}.html`)

        let resultPath = ''
        try {
          const result = await session.proc.exportHtml(outputPath)
          resultPath = result.path
        } catch (e: any) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: `Export failed: ${String(e?.message ?? e)}`
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        if (!resultPath) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              content: {
                type: 'text',
                text: 'Export failed: no output path returned by pi.'
              }
            }
          })
          return { stopReason: 'end_turn' }
        }

        const uri = `file://${resultPath}`

        // Emit a short prefix + a resource link. Many clients concatenate chunks into a single
        // assistant message, so this avoids the "link + duplicate plain text" look.
        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: {
              type: 'text',
              text: 'Session exported: '
            }
          }
        })

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: {
              type: 'resource_link',
              name: `pi-session-${safeSessionId}.html`,
              uri,
              mimeType: 'text/html',
              title: 'Session exported'
            }
          }
        })

        return { stopReason: 'end_turn' }
      }

      if (cmd === 'autocompact') {
        const mode = (args[0] ?? 'toggle').toLowerCase()
        let enabled: boolean | null = null
        if (mode === 'on' || mode === 'true' || mode === 'enable' || mode === 'enabled') enabled = true
        else if (mode === 'off' || mode === 'false' || mode === 'disable' || mode === 'disabled') enabled = false

        if (enabled === null) {
          // toggle: read current state and invert.
          const state = (await session.proc.getState()) as any
          const current = Boolean(state?.autoCompactionEnabled)
          enabled = !current
        }

        await session.proc.setAutoCompaction(enabled)

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'agent_message_chunk',
            content: {
              type: 'text',
              text: `Auto-compaction ${enabled ? 'enabled' : 'disabled'}.`
            }
          }
        })

        return { stopReason: 'end_turn' }
      }
    }

    const usageOut: { usage?: TurnUsage; summary?: TurnSummary; error?: string } = {}
    const result = await session.prompt(
      message,
      images,
      promptToSessionTitle(params.prompt) ?? undefined,
      signal,
      usageOut
    )

    // ACP v1 reports failures as request errors, not successful end_turn responses.
    if (result === 'error' && !session.wasCancelRequested()) {
      const reason = usageOut.error ?? 'Pi prompt failed'
      throw RequestError.internalError({ reason }, reason)
    }
    const stopReason: StopReason = result === 'error' ? 'cancelled' : result

    return {
      stopReason,
      ...(usageOut.usage ? { usage: usageOut.usage } : {}),
      ...(usageOut.summary ? { _meta: { piAcp: usageOut.summary } } : {})
    }
  }

  async steer(params: unknown): Promise<{ outcome: 'injected' | 'promptRequired' }> {
    const value = params as {
      sessionId?: unknown
      prompt?: unknown
      _meta?: { steering?: { idleBehavior?: unknown } }
    } | null
    if (
      !value ||
      typeof value.sessionId !== 'string' ||
      !Array.isArray(value.prompt) ||
      !value.prompt.length ||
      value.prompt.some(
        block => !block || block.type !== 'text' || typeof block.text !== 'string' || !block.text.trim()
      ) ||
      (value._meta?.steering?.idleBehavior !== undefined && value._meta.steering.idleBehavior !== 'promptRequired')
    ) {
      throw RequestError.invalidParams('Steering requires non-empty text prompt and idleBehavior promptRequired')
    }
    const session = this.sessions.maybeGet(value.sessionId)
    if (!session) throw RequestError.invalidParams('Unknown session')
    return session.steer(value.prompt.map(block => block.text).join('\n'))
  }

  async cancel(params: CancelNotification): Promise<void> {
    const session = this.sessions.maybeGet(params.sessionId)
    if (!session) return
    await session.cancel()
  }

  async listSessions(params: ListSessionsRequest): Promise<ListSessionsResponse> {
    // ACP: filter by cwd if provided.
    // Zed currently sends `{}` (no cwd), so we default to the last session cwd to
    // emulate pi's `/resume` picker (project-scoped).
    const all = listPiSessions()

    const effectiveCwd = (params as any).cwd ?? this.lastSessionCwd
    const filtered = effectiveCwd ? all.filter(s => s.cwd === effectiveCwd) : all

    // Cursor-based pagination (opaque cursor). For MVP, we use a simple numeric offset.
    // If cursor is invalid, treat as 0.
    const offset = params.cursor ? Number.parseInt(params.cursor, 10) : 0
    const start = Number.isFinite(offset) && offset > 0 ? offset : 0

    const PAGE_SIZE = 50
    const page = filtered.slice(start, start + PAGE_SIZE)

    const sessions: SessionInfo[] = page.map(s => ({
      sessionId: s.sessionId,
      cwd: s.cwd,
      title: s.title,
      updatedAt: s.updatedAt
    }))

    const nextCursor = start + PAGE_SIZE < filtered.length ? String(start + PAGE_SIZE) : null

    return { sessions, nextCursor, _meta: {} }
  }

  async loadSession(params: LoadSessionRequest): Promise<LoadSessionResponse> {
    if (!isAbsolute(params.cwd)) {
      throw RequestError.invalidParams(`cwd must be an absolute path: ${params.cwd}`)
    }
    warnAdditionalDirectories('session/load', (params as { additionalDirectories?: unknown }).additionalDirectories)
    const launch = parseLaunchOptions(params._meta)

    // If the client is re-loading a session that is already active, tear down the existing
    // pi subprocess so we can start fresh and re-advertise commands reliably.
    // (Some clients may call session/load when restoring from history.)
    this.sessions.close(params.sessionId)

    this.lastSessionCwd = params.cwd

    const enableSkillCommands = getEnableSkillCommands(params.cwd)
    const session = await this.restoreSession(params.sessionId, {
      cwd: params.cwd,
      mcpServers: params.mcpServers,
      launch
    })
    const proc = session.proc
    let configuration: Awaited<ReturnType<typeof getSessionConfiguration>>
    try {
      configuration = await getSessionConfiguration(proc)
    } catch (err) {
      this.sessions.close(session.sessionId)
      throw err
    }
    const { configOptions, models, modes } = configuration
    const fileCommands = loadSlashCommands(params.cwd)

    // Replay full conversation history.
    const data = (await proc.getMessages()) as any
    const messages = Array.isArray(data?.messages) ? data.messages : []
    session.seedMessageIds([])

    for (const m of messages) {
      const role = String(m?.role ?? '')

      if (role === 'user') {
        const messageId = session.messageIdForReplay(m)
        const text = normalizePiMessageText(m?.content)
        if (text) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'user_message_chunk',
              messageId,
              content: { type: 'text', text }
            }
          })
        }
      }

      if (role === 'assistant') {
        const messageId = session.messageIdForReplay(m)
        const thinking = normalizePiThoughtText(m?.content)
        if (thinking) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_thought_chunk',
              messageId: `${messageId}:thought`,
              content: { type: 'text', text: thinking }
            }
          })
        }
        const text = normalizePiAssistantText(m?.content)
        if (text) {
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'agent_message_chunk',
              messageId,
              content: { type: 'text', text }
            }
          })
        }
      }

      if (role === 'toolResult') {
        const toolName = String((m as any)?.toolName ?? 'tool')
        const toolCallId = String((m as any)?.toolCallId ?? crypto.randomUUID())
        const isError = Boolean((m as any)?.isError)
        const isBash = isBashTool(toolName)

        if (isBash) {
          const text = bashResultText(m)
          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'tool_call',
              toolCallId,
              title: bashCommand(m) ?? toolName,
              name: toolName,
              kind: 'execute',
              status: isError ? 'failed' : 'completed',
              content: bashTerminalContent(toolCallId),
              _meta: bashTerminalInfoMeta(toolCallId, params.cwd)
            }
          })

          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'tool_call_update',
              toolCallId,
              status: isError ? 'failed' : 'completed',
              rawOutput: m,
              _meta: {
                ...(text ? bashTerminalOutputMeta(toolCallId, text) : {}),
                ...bashTerminalExitMeta(toolCallId, bashExitCode(m, isError))
              }
            }
          })
          continue
        }

        // Create a synthetic ACP tool call to render historic tool usage.
        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'tool_call',
            toolCallId,
            title: toolName,
            name: toolName,
            kind: toToolKind(toolName),
            status: isError ? 'failed' : 'completed',
            rawInput: null,
            rawOutput: m
          }
        })

        const content = session.richToolContent(m)
        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'tool_call_update',
            toolCallId,
            status: isError ? 'failed' : 'completed',
            content: content.length ? content : null,
            rawOutput: m
          }
        })
      }
    }

    const response = {
      configOptions,
      models,
      modes,
      _meta: {
        piAcp: {
          startupInfo: null
        }
      }
    }

    // Advertise slash commands after the response so the client knows the session exists.
    setTimeout(() => {
      void (async () => {
        await session.publishContextUsage()

        try {
          const pi = (await proc.getCommands()) as any
          const { commands } = toAvailableCommandsFromPiGetCommands(pi, {
            enableSkillCommands,
            includeExtensionCommands: true
          })

          await this.conn.sessionUpdate({
            sessionId: session.sessionId,
            update: {
              sessionUpdate: 'available_commands_update',
              availableCommands: mergeCommands(commands, builtinAvailableCommands())
            }
          })
          return
        } catch {
          // fall back
        }

        await this.conn.sessionUpdate({
          sessionId: session.sessionId,
          update: {
            sessionUpdate: 'available_commands_update',
            availableCommands: mergeCommands(toAvailableCommands(fileCommands), builtinAvailableCommands())
          }
        })
      })()
    }, 0)

    return response
  }

  async forkSession(params: ForkSessionRequest): Promise<ForkSessionResponse> {
    if (!isAbsolute(params.cwd)) {
      throw RequestError.invalidParams(`cwd must be an absolute path: ${params.cwd}`)
    }
    warnAdditionalDirectories('session/fork', params.additionalDirectories)

    const sourceFile = await this.requireSessionFile(params.sessionId, this.cwds.get(params.sessionId) ?? params.cwd)

    const mcpInjection = params.mcpServers?.length ? prepareMcpInjection(params.mcpServers) : null
    let proc: PiRpcProcess
    try {
      proc = await PiRpcProcess.spawn({
        cwd: params.cwd,
        forkSessionPath: sourceFile,
        piCommand: process.env.PI_ACP_PI_COMMAND,
        ...(mcpInjection ? { mcpInjection } : {})
      })
    } catch (e: any) {
      mcpInjection?.cleanup()
      if (e?.name === 'PiRpcSpawnError') {
        throw RequestError.internalError({ code: e?.code }, String(e?.message ?? e))
      }
      throw e
    }

    let state: any = null
    try {
      state = (await proc.getState()) as any
    } catch {
      state = null
    }
    const sessionId = typeof state?.sessionId === 'string' ? state.sessionId : crypto.randomUUID()

    const fileCommands = loadSlashCommands(params.cwd)
    // Registers the forked session so subsequent requests address it directly.
    this.sessions.getOrCreate(sessionId, {
      cwd: params.cwd,
      mcpServers: params.mcpServers ?? [],
      conn: this.conn,
      proc,
      fileCommands,
      mcpInjection,
      clientCapabilities: this.clientCapabilities
    })

    try {
      this.lastSessionCwd = params.cwd
      this.cwds.set(sessionId, params.cwd)
      const { configOptions, modes } = await getSessionConfiguration(proc)
      return { sessionId, modes, configOptions }
    } catch (err) {
      this.sessions.close(sessionId)
      throw err
    }
  }

  async resumeSession(params: ResumeSessionRequest): Promise<ResumeSessionResponse> {
    if (!isAbsolute(params.cwd)) {
      throw RequestError.invalidParams(`cwd must be an absolute path: ${params.cwd}`)
    }

    const launch = parseLaunchOptions(params._meta)
    const existing = this.sessions.maybeGet(params.sessionId)
    if (existing && existing.trustedParent !== launch.trustedParent) {
      throw RequestError.invalidParams('Close the session before resuming with a different trustedParent value')
    }
    const session = await this.restoreSession(params.sessionId, {
      cwd: params.cwd,
      mcpServers: params.mcpServers ?? [],
      launch
    })
    // A live process cannot change its workspace or injected MCP descriptors.
    if (session.cwd !== params.cwd || !isDeepStrictEqual(session.mcpServers, params.mcpServers ?? [])) {
      throw RequestError.invalidParams('Close the session before resuming with a different cwd or MCP servers')
    }

    try {
      const { configOptions, modes } = await getSessionConfiguration(session.proc)
      if (!existing) {
        const data = await session.proc.getMessages()
        const messages = data && typeof data === 'object' && 'messages' in data ? data.messages : undefined
        session.seedMessageIds(Array.isArray(messages) ? messages : [])
      }
      this.lastSessionCwd = session.cwd
      return { configOptions, modes }
    } catch (err) {
      if (!existing) this.sessions.close(session.sessionId)
      throw err
    }
  }

  async closeSession(params: CloseSessionRequest): Promise<CloseSessionResponse> {
    // A restore already in progress must finish before its process can be reclaimed.
    await this.restoringSessions.get(params.sessionId)?.catch(() => {})
    this.sessions.close(params.sessionId)
    return {}
  }

  async deleteSession(params: DeleteSessionRequest): Promise<DeleteSessionResponse> {
    await this.closeSession(params)
    // The request carries no cwd: use the one this adapter knows, else the listing.
    // Per ACP session/delete semantics, deleting a session that does not
    // exist (or is already gone) should succeed idempotently.
    // https://agentclientprotocol.com/protocol/v2/session-delete#semantics
    const sessionFile =
      (await this.locateSessionFile(params.sessionId, this.cwds.get(params.sessionId))) ??
      listPiSessions().find(s => s.sessionId === params.sessionId)?.sessionFile

    if (sessionFile) {
      try {
        await unlink(sessionFile)
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code !== 'ENOENT') {
          throw RequestError.internalError({}, `Failed to delete session: ${String(err)}`)
        }
      }
    }

    this.cwds.delete(params.sessionId)

    return {}
  }

  async setSessionMode(params: SetSessionModeRequest): Promise<SetSessionModeResponse> {
    const session = await this.restoreSession(params.sessionId)

    const mode = params.modeId
    if (typeof mode !== 'string' || mode.length === 0) {
      throw RequestError.invalidParams('Expected nonempty string modeId')
    }

    await session.proc.setThinkingLevel(mode)

    await emitConfigOptionsUpdate(this.conn, session.sessionId, session.proc)

    return {}
  }

  async setSessionConfigOption(params: SetSessionConfigOptionRequest): Promise<SetSessionConfigOptionResponse> {
    const session = await this.restoreSession(params.sessionId)
    const configId = String(params.configId)
    let modelChanged = false

    if (typeof params.value !== 'string') {
      throw RequestError.invalidParams(`Expected string value for config option: ${configId}`)
    }

    if (configId === MODEL_CONFIG_ID) {
      await setSessionModel(session.proc, params.value)
      modelChanged = true
    } else if (configId === THOUGHT_LEVEL_CONFIG_ID) {
      if (params.value.length === 0) {
        throw RequestError.invalidParams('Expected nonempty thinking level')
      }

      await session.proc.setThinkingLevel(params.value)
    } else {
      throw RequestError.invalidParams(`Unknown config option: ${configId}`)
    }

    const configOptions = await emitConfigOptionsUpdate(this.conn, session.sessionId, session.proc)
    // A different model can mean a different context window; refresh it immediately.
    if (modelChanged) await session.publishContextUsage()
    return { configOptions }
  }
}

async function getThinkingState(
  proc: PiRpcProcess,
  pre?: { state?: any | null }
): Promise<{
  availableModes: Array<{
    id: string
    name: string
    description?: string | null
  }>
  currentModeId: string
}> {
  const state = pre?.state ?? (await proc.getState())
  const available = await proc.getAvailableThinkingLevels()
  const current: unknown =
    state && typeof state === 'object' && 'thinkingLevel' in state ? state.thinkingLevel : undefined
  if (typeof current !== 'string' || current.length === 0 || !available.includes(current)) {
    throw new Error('pi returned a thinking level absent from available levels')
  }

  return {
    currentModeId: current,
    availableModes: available.map(id => ({
      id,
      name: `Thinking: ${id}`,
      description: null
    }))
  }
}

async function getSessionConfiguration(
  proc: PiRpcProcess,
  pre?: { state?: any | null; availableModels?: any | null }
): Promise<{
  configOptions: SessionConfigOption[]
  models: {
    availableModels: AdvertisedModel[]
    currentModelId: string
  } | null
  modes: {
    availableModes: Array<{
      id: string
      name: string
      description?: string | null
    }>
    currentModeId: string
  }
}> {
  const state = pre?.state ?? (await proc.getState())
  const [models, modes] = await Promise.all([getModelState(proc, { ...pre, state }), getThinkingState(proc, { state })])

  return {
    configOptions: buildConfigOptions({ models, modes }),
    models,
    modes
  }
}

function buildConfigOptions(state: {
  models: {
    availableModels: AdvertisedModel[]
    currentModelId: string
  } | null
  modes: {
    availableModes: Array<{
      id: string
      name: string
      description?: string | null
    }>
    currentModeId: string
  }
}): SessionConfigOption[] {
  const configOptions: SessionConfigOption[] = [
    {
      type: 'select',
      id: THOUGHT_LEVEL_CONFIG_ID,
      category: 'thought_level',
      name: 'Thinking',
      description: 'Set the reasoning effort for this session',
      currentValue: state.modes.currentModeId,
      options: state.modes.availableModes.map(mode => ({
        value: mode.id,
        name: mode.name,
        description: mode.description ?? null
      }))
    }
  ]

  if (state.models?.availableModels.length) {
    configOptions.unshift({
      type: 'select',
      id: MODEL_CONFIG_ID,
      category: 'model',
      name: 'Model',
      description: 'Select the model for this session',
      currentValue: state.models.currentModelId,
      options: state.models.availableModels.map(model => ({
        value: model.modelId,
        name: model.name,
        description: model.description ?? null
      }))
    })
  }

  return configOptions
}

async function getModelState(
  proc: PiRpcProcess,
  pre?: { state?: any | null; availableModels?: any | null }
): Promise<{
  availableModels: AdvertisedModel[]
  currentModelId: string
} | null> {
  // Ask pi for available models.
  let availableModels: AdvertisedModel[] = []

  const data =
    pre?.availableModels ??
    (await (async () => {
      try {
        return (await proc.getAvailableModels()) as any
      } catch {
        return null
      }
    })())

  const models: any[] = Array.isArray(data?.models) ? data.models : []
  availableModels = models
    .map(m => {
      const provider = String(m?.provider ?? '').trim()
      const id = String(m?.id ?? '').trim()
      if (!provider || !id) return null

      const rawName = String(m?.name ?? '').trim()
      const modelId = `${provider}/${id}`
      // Some clients reject a model option whose display name equals its id;
      // derive a distinguishable name when pi's name is missing or identical.
      const name = rawName && rawName !== id ? `${provider}/${rawName}` : `${provider} ${id}`
      return {
        modelId,
        name,
        description: null
      } satisfies AdvertisedModel
    })
    .filter(Boolean) as AdvertisedModel[]

  // Ask pi what model is currently active.
  let currentModelId: string | null = null

  const state =
    pre?.state ??
    (await (async () => {
      try {
        return (await proc.getState()) as any
      } catch {
        return null
      }
    })())

  const model = state?.model
  if (model && typeof model === 'object') {
    const provider = String((model as any).provider ?? '').trim()
    const id = String((model as any).id ?? '').trim()
    if (provider && id) currentModelId = `${provider}/${id}`
  }

  if (!availableModels.length && !currentModelId) return null

  // Fallback if current model is unknown: use first in list.
  if (!currentModelId) currentModelId = availableModels[0]?.modelId ?? 'default'

  return {
    availableModels,
    currentModelId: currentModelId ?? availableModels[0]?.modelId ?? 'default'
  }
}

async function emitConfigOptionsUpdate(
  conn: AcpClient,
  sessionId: string,
  proc: PiRpcProcess
): Promise<SessionConfigOption[]> {
  const { configOptions, modes } = await getSessionConfiguration(proc)

  await conn.sessionUpdate({
    sessionId,
    update: { sessionUpdate: 'current_mode_update', currentModeId: modes.currentModeId }
  })
  await conn.sessionUpdate({
    sessionId,
    update: {
      sessionUpdate: 'config_option_update',
      configOptions
    }
  })

  return configOptions
}

async function setSessionModel(proc: PiRpcProcess, requestedModelId: string): Promise<void> {
  // Accept either:
  //  - "provider/model" (preferred, matches how we advertise)
  //  - "model" (fallback, resolve via available models)
  let provider: string | null = null
  let modelId: string | null = null

  if (requestedModelId.includes('/')) {
    const [candidateProvider, ...rest] = requestedModelId.split('/')
    provider = candidateProvider
    modelId = rest.join('/')
  } else {
    modelId = requestedModelId
  }

  if (!provider) {
    const data = (await proc.getAvailableModels()) as any
    const models: any[] = Array.isArray(data?.models) ? data.models : []
    const found = models.find(m => String(m?.id) === modelId)
    if (found) {
      provider = String(found.provider)
      modelId = String(found.id)
    }
  }

  if (!provider || !modelId) {
    throw RequestError.invalidParams(`Unknown modelId: ${requestedModelId}`)
  }

  await proc.setModel(provider, modelId)
}

function isSemver(v: string): boolean {
  return /^\d+\.\d+\.\d+(?:[-+].+)?$/.test(v)
}

function compareSemver(a: string, b: string): number {
  // Very small comparator for x.y.z (ignores pre-release/build beyond making them "not greater" unless base differs)
  const pa = a
    .split(/[.-]/)
    .slice(0, 3)
    .map(n => Number(n))
  const pb = b
    .split(/[.-]/)
    .slice(0, 3)
    .map(n => Number(n))
  for (let i = 0; i < 3; i++) {
    const da = pa[i] ?? 0
    const db = pb[i] ?? 0
    if (da > db) return 1
    if (da < db) return -1
  }
  return 0
}

function buildMcpStartupSection(plan: McpInjectionPlan | null | undefined): string {
  if (!plan || (!plan.serverNames.length && !plan.warnings.length)) return ''

  const lines = ['## MCP', '']
  if (plan.serverNames.length) {
    lines.push(`- Injected ${plan.serverNames.length} client server(s): ${plan.serverNames.join(', ')}`)
  }
  for (const warning of plan.warnings) lines.push(`- ${warning}`)
  lines.push('')
  return lines.join('\n')
}

/** Best-effort trimmed stdout of a short-lived probe command; never rejects. */
async function probeOutput(file: string, args: string[], timeoutMs: number): Promise<string | null> {
  try {
    const { stdout } = await execFile(file, args, { encoding: 'utf-8', timeout: timeoutMs })
    return String(stdout ?? '').trim() || null
  } catch (err: any) {
    // Non-zero exit still counts (pi prints its version to stdout or stderr).
    return String(err?.stdout ?? '').trim() || String(err?.stderr ?? '').trim() || null
  }
}

async function probeVersions(): Promise<{ installed: string | null; latest: string | null }> {
  const installedRaw = (await probeOutput('pi', ['--version'], 800))?.replace(/^v/i, '') ?? ''
  if (!installedRaw || !isSemver(installedRaw)) return { installed: null, latest: null }
  const latestRaw = (await probeOutput('npm', ['view', '@earendil-works/pi-coding-agent', 'version'], 800))?.replace(
    /^v/i,
    ''
  )
  return { installed: installedRaw, latest: latestRaw && isSemver(latestRaw) ? latestRaw : null }
}

function buildUpdateNotice(installed: string | null, latest: string | null): string | null {
  if (!installed || !latest) return null
  if (compareSemver(latest, installed) <= 0) return null
  return `New version available: v${latest} (installed v${installed}). Run: \`npm i -g @earendil-works/pi-coding-agent\``
}

function buildStartupInfo(opts: {
  cwd: string
  fileCommands: ReturnType<typeof loadSlashCommands>
  updateNotice: string | null
  piVersion: string | null
}): string {
  void opts.fileCommands

  const md: string[] = []

  // pi version header
  if (opts.piVersion) {
    md.push(`pi v${opts.piVersion}`)
    md.push('---')
    md.push('')
  }

  const addSection = (title: string, items: string[]) => {
    const cleaned = items.map(s => s.trim()).filter(Boolean)
    if (!cleaned.length) return

    md.push(`## ${title}`)
    for (const item of cleaned) md.push(`- ${item}`)
    md.push('')
  }

  // Context
  const contextItems: string[] = []
  const contextPath = join(opts.cwd, 'AGENTS.md')
  if (existsSync(contextPath)) contextItems.push(contextPath)
  addSection('Context', contextItems)

  // Skills
  const skillsItems: string[] = []

  const pushSkillFromRoot = (root: string) => {
    try {
      // Direct .md files in root
      for (const e of readdirSync(root)) {
        const p = join(root, e)
        try {
          const st = statSync(p)
          if (st.isFile() && e.toLowerCase().endsWith('.md')) {
            skillsItems.push(p)
          }
        } catch {
          // ignore
        }
      }

      // Recursive SKILL.md under subdirectories
      const stack: string[] = [root]
      while (stack.length) {
        const dir = stack.pop()!
        let entries: string[] = []
        try {
          entries = readdirSync(dir)
        } catch {
          continue
        }

        for (const name of entries) {
          // Skip obvious noise
          if (name === 'node_modules' || name === '.git') continue
          const p = join(dir, name)
          let st
          try {
            st = statSync(p)
          } catch {
            continue
          }
          if (st.isDirectory()) {
            stack.push(p)
          } else if (st.isFile() && name === 'SKILL.md') {
            skillsItems.push(p)
          }
        }
      }
    } catch {
      // ignore
    }
  }

  // Global skills
  // Use getAgentDir() so this respects PI_CODING_AGENT_DIR overrides.
  const globalSkillsDir = join(getAgentDir(), 'skills')
  pushSkillFromRoot(globalSkillsDir)

  // Also support ~/.agents/skills (pi skill discovery)
  const legacyAgentsSkillsDir = join(process.env.HOME ?? '', '.agents', 'skills')
  pushSkillFromRoot(legacyAgentsSkillsDir)

  // Project skills (.pi/skills)
  const projectSkillsDir = join(opts.cwd, '.pi', 'skills')
  pushSkillFromRoot(projectSkillsDir)

  addSection('Skills', skillsItems)

  // Prompts
  const promptsItems: string[] = []
  const promptsDir = join(process.env.HOME ?? '', '.pi', 'agent', 'prompts')
  try {
    const prompts = readdirSync(promptsDir).filter(f => f.endsWith('.md'))
    for (const f of prompts) promptsItems.push(`/${basename(f, '.md')}`)
  } catch {
    // ignore
  }
  addSection('Prompts', promptsItems)

  // Extensions
  const extItems: string[] = []
  const extDir = join(process.env.HOME ?? '', '.pi', 'agent', 'extensions')
  try {
    const exts = readdirSync(extDir).filter(f => f.endsWith('.ts') || f.endsWith('.js'))
    for (const f of exts) extItems.push(join(extDir, f))
  } catch {
    // ignore
  }

  // Also show npm packages from pi settings (global + project)
  const settingsPaths = [join(getAgentDir(), 'settings.json'), join(opts.cwd, '.pi', 'settings.json')]
  for (const settingsPath of settingsPaths) {
    try {
      const settings = JSON.parse(readFileSync(settingsPath, 'utf-8')) as any
      const pkgs: string[] = Array.isArray(settings?.packages) ? settings.packages : []
      for (const pkg of pkgs) {
        const s = String(pkg)
        if (s.startsWith('npm:')) {
          extItems.push(`${s}\n  - index.ts`)
        } else {
          extItems.push(s)
        }
      }
    } catch {
      // ignore
    }
  }

  addSection('Extensions', extItems)

  if (opts.updateNotice) {
    md.push('---')
    md.push(opts.updateNotice)
    md.push('')
  }

  // Do NOT include themes (per request).
  return md.join('\n').trim() + '\n'
}

function readNearestPackageJson(metaUrl: string): {
  name?: string
  version?: string
} {
  try {
    let dir = dirname(fileURLToPath(metaUrl))

    // Walk upwards a few levels to find the nearest package.json
    for (let i = 0; i < 6; i++) {
      const p = join(dir, 'package.json')
      if (existsSync(p)) {
        const json = JSON.parse(readFileSync(p, 'utf-8')) as any
        return { name: json?.name, version: json?.version }
      }
      dir = dirname(dir)
    }
  } catch {
    // ignore
  }
  return { name: 'pi-acp', version: '0.0.0' }
}
